card.statement:
For any complex numbers $a$ and $v_{ij}$, $1\leq j\leq i\leq 3$, consider the following Gelfand-Tsetlin tableaux.

\begin{center} \Stone{$v_{31}$}\Stone{$v_{32}$}\Stone{$v_{33}$} \Stone{$a$}\Stone{$a$}\Stone{$a$} [0.2pt] $T(v)$= \Stone{$v_{21}$}\Stone{$v_{22}$} $T(\bar{v})$= \Stone{$a$}\Stone{$a$} [0.2pt] \Stone{$v_{11}$} \Stone{$a$}

\end{center}

Consider $w=(0,1,0)=\delta^{22}$ and $w'=(1,0,0)=\delta^{21}$ in $\mathbb{Z}^{3}$. Then the following hold.

- [(i)] Using (<<ref:Formula: action of E on regular tableaux>>), $E_{32}(T(\bar{v}+w)) = \mathcal{D}^{\bar{v}}((v_{21}-v_{22})E_{32}(T(v+w)))$ which equals to: {

\begin{align*}
&\mathcal{D}^{\bar{v}}\left((v_{21}-v_{22})\left(\frac{v_{21}-v_{11}}{v_{21}-(v_{22}+1)}T(v+w-\delta^{21})+\frac{(v_{22}+1)-v_{11}}{(v_{22}+1)-v_{21}}T(v+w-\delta^{22})\right)\right)\\
=& \mathcal{D}^{\bar{v}}\left(\frac{(v_{21}-v_{22})(v_{21}-v_{11})}{v_{21}-(v_{22}+1)}\right)T(\bar{w}-\delta^{21})+ ev({\bar{v}})\left(\frac{(v_{21}-v_{22})(v_{21}-v_{11})}{v_{21}-(v_{22}+1)}\right)\mathcal{D}T(\bar{w}-\delta^{21})\\
&+ \mathcal{D}^{\bar{v}}\left(\frac{(v_{21}-v_{22})((v_{22}+1)-v_{11})}{(v_{22}+1)-v_{21}}\right)T(\bar{v})+ ev({\bar{v}})\left(\frac{(v_{21}-v_{22})((v_{22}+1)-v_{11})}{(v_{22}+1)-v_{21}}\right)\mathcal{D}T(\bar{v})\\
=& ev({\bar{v}})\left(\frac{v_{21}-v_{11}}{v_{21}-(v_{22}+1)}\right)T(\bar{w}-\delta^{21})+ ev({\bar{v}})\left(\frac{(v_{21}-v_{22})(v_{21}-v_{11})}{v_{21}-(v_{22}+1)}\right)\mathcal{D}T(\bar{w}-\delta^{21})\\
&+ ev({\bar{v}})\left(\frac{(v_{22}+1)-v_{11}}{(v_{22}+1)-v_{21}}\right)T(\bar{v})\\
=& T(\bar{v}).
\end{align*}

}

- [(ii)] Using (<<ref:Formula: action of E on derivative tableaux>>), $E_{32}(\mathcal{D}T(\bar{v}+w'))=\mathcal{D}^{\bar{v}}(E_{32}(T(v+w')))$ which equals to: {

\begin{align*}
& \mathcal{D}^{\bar{v}}\left(\frac{v_{21}+1-v_{11}}{v_{21}+1-v_{22}}T(v+w'-\delta^{21})\right)+ \mathcal{D}^{\bar{v}}\left(\frac{v_{22}-v_{11}}{v_{22}-(v_{21}+1)}T(v+w'-\delta^{22})\right)\\
=& \mathcal{D}^{\bar{v}}\left(\frac{v_{21}+1-v_{11}}{v_{21}+1-v_{22}}\right)T(\bar{v})+ ev({\bar{v}})\left(\frac{v_{21}+1-v_{11}}{v_{21}+1-v_{22}}\right)\mathcal{D}T(\bar{v})\\
&+ \mathcal{D}^{\bar{v}}\left(\frac{v_{22}-v_{11}}{v_{22}-(v_{21}+1)}\right)T(\bar{v}+\delta^{21}-\delta^{22})+ ev({\bar{v}})\left(\frac{v_{22}-v_{11}}{v_{22}-(v_{21}+1)}\right)\mathcal{D}T(\bar{v}+\delta^{21}-\delta^{22})\\
=& \mathcal{D}^{\bar{v}}\left(\frac{v_{21}+1-v_{11}}{v_{21}+1-v_{22}}\right)T(\bar{v})+ \mathcal{D}^{\bar{v}}\left(\frac{v_{22}-v_{11}}{v_{22}-(v_{21}+1)}\right)T(\bar{v}+\delta^{21}-\delta^{22})\\
=& \frac{1}{2}T(\bar{v})-\frac{1}{2}T(\bar{v}+\delta^{21}-\delta^{22}).
\end{align*}

}
